INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4850, 'pay stub', '/peɪ stʌb/', 'noun', '{"zh-TW":["薪資單；工資單"],"en":["a document detailing an employee''s earnings and deductions for a pay period"]}', NULL, 'review pay stub / pay stub information / digital pay stub', '[{"en":"She reviewed her pay stub to verify the overtime payment.","zh-TW":"她查看薪資單以核實加班費。"},{"en":"Pay stubs are required as proof of income for loan applications.","zh-TW":"薪資單作為貸款申請的收入證明是必需的。"}]', '{"plural":"pay stubs","alternative":"payslip"}', NULL, 3, 4850, NULL),
(4851, 'pay-per-click', '/peɪ pər klɪk/', 'noun', '{"zh-TW":["每次點擊付費廣告"],"en":["an online advertising model where advertisers pay per click on their ad"]}', NULL, 'run a pay-per-click campaign / pay-per-click advertising', '[{"en":"Pay-per-click campaigns generated 500 new leads this month.","zh-TW":"每次點擊付費廣告活動本月產生了500個新潛在客戶。"},{"en":"Google Ads operates on a pay-per-click model.","zh-TW":"Google廣告採用每次點擊付費模式運作。"}]', '{"abbreviation":"PPC"}', NULL, 5, 4851, NULL),
(4852, 'payable', '/ˈpeɪəbəl/', 'adjective', '{"zh-TW":["應付的；可支付的"],"en":["that must be or can be paid"]}', NULL, 'payable on demand / accounts payable', '[{"en":"The amount is payable upon receipt of the invoice.","zh-TW":"金額在收到發票後支付。"},{"en":"Please make the check payable to the company name.","zh-TW":"請將支票抬頭填寫為公司名稱。"}]', NULL, NULL, 3, 4852, 901),
(4853, 'payables management', '/ˈpeɪəblz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["應付帳款管理"],"en":["the process of tracking and managing amounts owed to suppliers"]}', NULL, 'improve payables management / payables management cycle', '[{"en":"Effective payables management optimizes cash flow by timing payments.","zh-TW":"有效的應付帳款管理通過安排付款時間來優化現金流。"},{"en":"The finance team reviews payables management metrics monthly.","zh-TW":"財務團隊每月審查應付帳款管理指標。"}]', NULL, NULL, 5, 4853, NULL),
(4854, 'payback period', '/ˈpeɪbæk ˈpɪəriəd/', 'noun', '{"zh-TW":["回收期"],"en":["the time required to recover the cost of an investment"]}', NULL, 'calculate payback period / short payback period / payback period analysis', '[{"en":"The equipment has a payback period of three years.","zh-TW":"設備的回收期為三年。"},{"en":"A shorter payback period reduces investment risk.","zh-TW":"較短的回收期降低了投資風險。"}]', NULL, NULL, 5, 4854, NULL),
(4855, 'payload', '/ˈpeɪləʊd/', 'noun', '{"zh-TW":["有效負載；數據包"],"en":["the data carried in a transmission; the actual data delivered to the destination"]}', NULL, 'request payload / response payload / encrypted payload', '[{"en":"The API accepts a JSON payload with up to ten fields.","zh-TW":"API接受最多包含十個字段的JSON有效負載。"},{"en":"The malicious payload was hidden inside a seemingly normal file.","zh-TW":"惡意有效負載隱藏在看似正常的文件中。"}]', NULL, NULL, 3, 4855, NULL),
(4856, 'payment', 'ˈpeɪmənt', 'noun', '{"zh-TW":["付款；支付","薪酬"],"en":["the action of paying money","a sum paid"]}', NULL, 'make a payment/overdue payment', '[{"en":"Payment is due within 30 days.","zh-TW":"付款應在30天內完成。"}]', '{"verb":"pay","adjective":"paid"}', NULL, 3, 4856, 171),
(4857, 'payment terms', '/ˈpeɪmənt tɜːrmz/', 'noun', '{"zh-TW":["付款條款"],"en":["the conditions specifying when and how payment is to be made"]}', NULL, 'agree on payment terms / standard payment terms', '[{"en":"The standard payment terms are 30 days from invoice date.","zh-TW":"標準付款條款為發票日期後30天。"},{"en":"Negotiating longer payment terms helps manage working capital.","zh-TW":"談判更長的付款條款有助於管理營運資金。"}]', NULL, NULL, 5, 4857, NULL),
(4858, 'payout ratio', '/ˈpeɪaʊt ˈreɪʃioʊ/', 'noun', '{"zh-TW":["股息支付比率"],"en":["the fraction of earnings paid as dividends to shareholders"]}', NULL, 'calculate payout ratio / high payout ratio', '[{"en":"A payout ratio above 80% leaves little for reinvestment.","zh-TW":"高於80%的股息支付比率幾乎沒有留下再投資的空間。"},{"en":"Growth companies tend to have lower payout ratios.","zh-TW":"成長型公司往往有較低的股息支付比率。"}]', NULL, NULL, 4, 4858, NULL),
(4859, 'payroll', '/ˈpeɪroʊl/', 'noun', '{"zh-TW":["薪資名冊；薪資發放"],"en":["the total of wages paid by a company to its employees; the process of paying employees"]}', NULL, 'process payroll / payroll system / payroll taxes / payroll management', '[{"en":"The payroll is processed on the last working day of each month.","zh-TW":"薪資在每月最後一個工作日發放。"},{"en":"Payroll software automates tax calculations and direct deposits.","zh-TW":"薪資軟體自動計算稅款和直接匯款。"}]', '{"noun":"payroll administrator"}', NULL, 3, 4859, 902),
(4860, 'payroll processing', '/ˈpeɪroʊl ˈprɒsesɪŋ/', 'noun', '{"zh-TW":["薪資處理"],"en":["the administrative task of calculating and distributing employee salaries and deductions"]}', NULL, 'manage payroll processing / payroll processing software', '[{"en":"Automated payroll processing reduces errors and saves time.","zh-TW":"自動化薪資處理減少了錯誤並節省了時間。"},{"en":"The payroll processing team meets strict deadlines every month.","zh-TW":"薪資處理團隊每月都要遵守嚴格的截止日期。"}]', NULL, NULL, 5, 4860, NULL),
(4861, 'payroll system', '/ˈpeɪroʊl ˈsɪstəm/', 'noun', '{"zh-TW":["薪資系統；薪酬系統"],"en":["the software or process used to calculate and distribute employee salaries"]}', NULL, 'implement a payroll system / payroll system upgrade', '[{"en":"The new payroll system automates tax deductions and payments.","zh-TW":"新的薪資系統自動化了稅款扣除和支付。"},{"en":"The payroll system was migrated to cloud-based software.","zh-TW":"薪資系統遷移到了雲端軟體。"}]', NULL, NULL, 5, 4861, NULL),
(4862, 'peace', '/piːs/', 'noun', '{"zh-TW":["和平；平靜"],"en":["freedom from disturbance","a state of calm"]}', NULL, 'peace of mind / keep the peace', '[{"en":"Insurance gives you peace of mind.","zh-TW":"保險讓你安心。"},{"en":"We want to keep the peace in the office.","zh-TW":"我們希望維持辦公室的和諧。"}]', '{"noun":"peace","adjective":"peaceful","adverb":"peacefully"}', NULL, 2, 4862, NULL),
(4863, 'peak', '/piːk/', 'noun', '{"zh-TW":["高峰；頂點"],"en":["the highest point"]}', NULL, 'peak season / reach a peak / peak performance', '[{"en":"Sales reached their peak in December.","zh-TW":"銷售在十二月達到高峰。"},{"en":"Peak hours are from 8 to 10 AM.","zh-TW":"高峰時段是早上8到10點。"}]', '{"adjective":"peak","verb":"peak"}', NULL, 1, 4863, NULL),
(4864, 'peak demand', '/piːk dɪˈmɑːnd/', 'noun', '{"zh-TW":["需求高峰；尖峰需求"],"en":["the period of highest demand for a product or service"]}', NULL, 'manage peak demand / peak demand planning', '[{"en":"Extra staff were hired to handle peak demand during the holiday season.","zh-TW":"額外員工被聘用以處理假期季節的需求高峰。"},{"en":"Forecasting peak demand allows inventory to be stocked in advance.","zh-TW":"預測需求高峰允許提前備貨。"}]', NULL, NULL, 4, 4864, NULL),
(4865, 'peak season', '/''piːk ˌsiːzən/', 'noun', '{"zh-TW":["旺季；高峰季節"],"en":["the time of year when a place is most popular with visitors and prices are typically higher"]}', NULL, 'travel during peak season / avoid peak season / peak season prices', '[{"en":"Hotels and flights are significantly more expensive during peak season.","zh-TW":"在旺季，飯店和航班的費用要貴得多。"},{"en":"She booked her trip in shoulder season to avoid the peak season crowds.","zh-TW":"她在淡旺季之間預訂了旅行，以避開旺季的人群。"}]', NULL, NULL, 4, 4865, NULL),
(4866, 'pecuniary', '/pɪˈkjuːniəri/', 'adjective', '{"zh-TW":["金錢的；財務的"],"en":["relating to or consisting of money"]}', NULL, 'pecuniary interest / pecuniary gain / pecuniary penalty', '[{"en":"A judge must declare any pecuniary interest in a case before hearing it.","zh-TW":"法官在審理案件前必須聲明任何金錢利益。"},{"en":"The employee faced pecuniary penalties for violating the confidentiality agreement.","zh-TW":"這名員工因違反保密協議而面臨金錢懲罰。"}]', '{"adverb":"pecuniarily"}', NULL, 3, 4866, NULL),
(4867, 'pedagogical', '/ˌpedəˈɡɒdʒɪkəl/', 'adjective', '{"zh-TW":["教學法的；教育的"],"en":["relating to teaching or education methods"]}', NULL, 'pedagogical approach / pedagogical strategy / pedagogical framework', '[{"en":"The pedagogical approach should match the learner''s level.","zh-TW":"教學方法應與學習者的程度相符。"},{"en":"She proposed a new pedagogical framework for online learning.","zh-TW":"她提出了一種新的線上學習教學框架。"}]', '{"noun":"pedagogy","adverb":"pedagogically"}', NULL, 4, 4867, NULL),
(4868, 'pedagogy', '/''pedəɡɒdʒi/', 'noun', '{"zh-TW":["教學法；教育學"],"en":["the method and practice of teaching, especially as an academic subject or theoretical concept"]}', NULL, 'modern pedagogy / pedagogy training / teaching pedagogy', '[{"en":"The university offers a course in pedagogy for aspiring teachers.","zh-TW":"該大學為有志成為教師的人提供教學法課程。"},{"en":"Student-centered pedagogy focuses on involving students actively in the learning process.","zh-TW":"以學生為中心的教學法專注於讓學生積極參與學習過程。"}]', '{"adjective":"pedagogical","noun":"pedagogue"}', NULL, 3, 4868, NULL),
(4869, 'pediatrics', '/ˌpiːdiˈætrɪks/', 'noun', '{"zh-TW":["兒科；小兒科"],"en":["the branch of medicine dealing with children''s health"]}', NULL, 'pediatrics clinic / pediatrics specialist', '[{"en":"The pediatrics clinic is open on weekday mornings.","zh-TW":"兒科診所在平日早晨開放。"},{"en":"Pediatrics specialists monitor children''s development and health.","zh-TW":"兒科專科醫生監測兒童的發展和健康。"}]', '{"noun":"pediatrician","adjective":"pediatric"}', NULL, 4, 4869, NULL),
(4870, 'peer comparison', '/pɪər kəmˈpærɪsən/', 'noun', '{"zh-TW":["同業比較"],"en":["the evaluation of a company''s performance relative to similar companies"]}', NULL, 'conduct a peer comparison / peer comparison analysis', '[{"en":"The peer comparison showed the company ranked third in profit margins.","zh-TW":"同業比較顯示公司在利潤率方面排名第三。"},{"en":"Investors use peer comparison to identify undervalued stocks.","zh-TW":"投資者使用同業比較來識別被低估的股票。"}]', NULL, NULL, 5, 4870, NULL),
(4871, 'peer learning', '/''pɪər ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["同伴學習；互動學習"],"en":["a method of learning where students teach and support each other"]}', NULL, 'encourage peer learning / peer learning session / benefit of peer learning', '[{"en":"Peer learning allows students to reinforce their own understanding by teaching others.","zh-TW":"同伴學習讓學生通過教導他人來鞏固自己的理解。"},{"en":"Group projects promote peer learning and develop teamwork skills.","zh-TW":"小組項目促進同伴學習並培養團隊合作技能。"}]', NULL, NULL, 5, 4871, NULL),
(4872, 'peer mentoring', '/''pɪər ˌmentərɪŋ/', 'noun', '{"zh-TW":["同儕輔導；同伴指導"],"en":["a support system in which more experienced students guide and assist their peers"]}', NULL, 'participate in peer mentoring / peer mentoring program / offer peer mentoring', '[{"en":"The peer mentoring program pairs incoming students with upperclassmen to ease the transition.","zh-TW":"同儕輔導計劃將新生與高年級學生配對，以便順利過渡。"},{"en":"She found peer mentoring more helpful than office hours because she could speak freely.","zh-TW":"她發現同儕輔導比辦公室時間更有幫助，因為她可以自由發言。"}]', '{"verb":"mentor","noun":"peer mentor"}', NULL, 5, 4872, NULL),
(4873, 'peer review', '/pɪər rɪˈvjuː/', 'noun', '{"zh-TW":["同儕審查；同行審閱"],"en":["evaluation of work by others in the same field"]}', NULL, 'undergo peer review / peer review process', '[{"en":"The research paper underwent rigorous peer review before publication.","zh-TW":"研究論文在發表前經過了嚴格的同儕審查。"},{"en":"Peer reviews help maintain high standards in academic and professional settings.","zh-TW":"同儕審查有助於在學術和專業環境中保持高標準。"}]', '{"verb":"peer review"}', NULL, 4, 4873, NULL),
(4874, 'peer socialization', '/pɪər ˌsəʊʃəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["同伴社會化"],"en":["the process by which individuals learn social norms through interaction with peers"]}', NULL, 'peer socialization process / role of peer socialization / peer socialization effects', '[{"en":"Peer socialization is especially powerful during adolescence.","zh-TW":"同伴社會化在青少年期尤其具有影響力。"},{"en":"Peer socialization can reinforce both prosocial and antisocial behaviors.","zh-TW":"同伴社會化可以強化親社會和反社會行為兩者。"}]', NULL, NULL, 5, 4874, NULL),
(4875, 'peg', '/peɡ/', 'verb', '{"zh-TW":["掛鈎；固定"],"en":["to fix a currency''s exchange rate to another currency or commodity"]}', NULL, 'peg the currency / currency peg', '[{"en":"The country pegged its currency to the US dollar to stabilize trade.","zh-TW":"該國將其貨幣與美元掛鈎以穩定貿易。"},{"en":"Maintaining a currency peg requires substantial foreign exchange reserves.","zh-TW":"維持貨幣掛鈎需要大量的外匯儲備。"}]', '{"noun":"peg","noun2":"currency peg"}', NULL, 1, 4875, NULL),
(4876, 'penalty', '/ˈpɛnəlti/', 'noun', '{"zh-TW":["罰款；處罰"],"en":["a punishment for breaking a rule"]}', '{"root":{"text":"pen","meaning":"punish (懲罰)"},"suffix":{"text":"-alty","meaning":"狀態"}}', 'pay a penalty / penalty clause / impose a penalty', '[{"en":"Late payment will incur a penalty.","zh-TW":"逾期付款將產生罰款。"},{"en":"The penalty for breach of contract is severe.","zh-TW":"違約的處罰很嚴重。"}]', '{"verb":"penalize","adjective":"penal"}', NULL, 3, 4876, NULL),
(4877, 'penalty clause', '/ˈpenəlti klɔːz/', 'noun', '{"zh-TW":["罰款條款；違約金條款"],"en":["a contractual provision imposing a financial penalty for non-performance"]}', NULL, 'include a penalty clause / trigger the penalty clause', '[{"en":"The penalty clause specified 500 per day for late delivery.","zh-TW":"罰款條款規定每天延遲交貨罰款500元。"},{"en":"The penalty clause was enforced after repeated missed deadlines.","zh-TW":"在多次錯過截止日期後，罰款條款被執行。"}]', NULL, NULL, 5, 4877, NULL),
(4878, 'penalty interest', '/ˈpenəlti ˈɪntrəst/', 'noun', '{"zh-TW":["罰息；違約利息"],"en":["additional interest charged on overdue payments"]}', NULL, 'charge penalty interest / penalty interest rate', '[{"en":"Penalty interest of 2% per month is applied to late invoices.","zh-TW":"逾期發票按每月2%計算罰息。"},{"en":"The supplier waived the penalty interest as a gesture of goodwill.","zh-TW":"供應商作為善意表示免除了罰息。"}]', NULL, NULL, 5, 4878, NULL),
(4879, 'pending', '/ˈpɛndɪŋ/', 'adjective', '{"zh-TW":["待定的；未決的"],"en":["awaiting decision; not yet resolved"]}', '{"root":{"text":"pend","meaning":"hang (懸掛)"}}', 'pending approval / pending investigation', '[{"en":"The application is still pending.","zh-TW":"申請仍在審核中。"},{"en":"Pending approval, we will proceed.","zh-TW":"待批准後我們將繼續。"}]', NULL, NULL, 3, 4879, 411),
(4880, 'penetration pricing', '/ˌpenɪˈtreɪʃən ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["滲透定價策略"],"en":["setting a low initial price to quickly gain market share"]}', NULL, 'use penetration pricing / penetration pricing strategy', '[{"en":"Penetration pricing helped the new service gain 100,000 users quickly.","zh-TW":"滲透定價幫助新服務迅速獲得了100,000名用戶。"},{"en":"The risk of penetration pricing is thin margins early on.","zh-TW":"滲透定價的風險是早期利潤率薄。"}]', NULL, NULL, 5, 4880, NULL),
(4881, 'penetration rate', '/ˌpenɪˈtreɪʃən reɪt/', 'noun', '{"zh-TW":["滲透率；市場佔有率"],"en":["the percentage of potential customers actually using a product or service"]}', NULL, 'increase penetration rate / low penetration rate / market penetration rate', '[{"en":"The smartphone penetration rate has reached near saturation in developed markets.","zh-TW":"智慧型手機在已開發市場的滲透率已接近飽和。"},{"en":"Electric vehicle penetration rates are growing rapidly in several European countries.","zh-TW":"電動車的滲透率在幾個歐洲國家正在快速增長。"}]', NULL, NULL, 5, 4881, NULL),
(4882, 'pension', '/ˈpɛnʃən/', 'noun', '{"zh-TW":["退休金"],"en":["regular payment after retirement"]}', '{"root":{"text":"pens","meaning":"pay (支付)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'pension plan / pension fund / retirement pension', '[{"en":"The company offers a generous pension plan.","zh-TW":"公司提供優厚的退休金計劃。"},{"en":"She retired with a full pension.","zh-TW":"她領取全額退休金退休。"}]', '{"noun":"pensioner"}', NULL, 3, 4882, NULL),
(4883, 'pension fund', '/ˈpenʃən fʌnd/', 'noun', '{"zh-TW":["退休基金；養老基金"],"en":["a pool of money invested to provide retirement income"]}', NULL, 'manage a pension fund / pension fund investment', '[{"en":"The pension fund invests in a mix of equities and bonds.","zh-TW":"退休基金投資於股票和債券的組合。"},{"en":"The company''s pension fund liability grew with an aging workforce.","zh-TW":"隨著員工老齡化，公司的退休基金負債增加了。"}]', NULL, NULL, 4, 4883, NULL),
(4884, 'penthouse', '/ˈpɛnthaʊs/', 'noun', '{"zh-TW":["頂樓豪華套房"],"en":["a luxury apartment or suite on the top floor"]}', NULL, 'penthouse suite / stay in a penthouse', '[{"en":"The penthouse offers stunning panoramic views.","zh-TW":"頂樓豪華套房提供令人驚嘆的全景視野。"},{"en":"The penthouse suite is the most exclusive room in the hotel.","zh-TW":"頂樓豪華套房是飯店最尊榮的房型。"}]', NULL, NULL, 3, 4884, NULL),
(4885, 'people', '/ˈpiːpəl/', 'noun', '{"zh-TW":["人們"],"en":["human beings in general"]}', NULL, 'people skills / people management', '[{"en":"Good people skills are essential for managers.","zh-TW":"良好的人際交往能力對管理者至關重要。"},{"en":"We put people first.","zh-TW":"我們以人為本。"}]', '{"noun":"people","noun2":"person","adjective":"personal"}', NULL, 2, 4885, NULL),
(4886, 'per annum', '/pɜːr ˈænəm/', 'adverb', '{"zh-TW":["每年；按年"],"en":["for each year; yearly"]}', NULL, 'grow 5% per annum / interest per annum', '[{"en":"The company has grown at 10% per annum for the last five years.","zh-TW":"公司過去五年每年增長10%。"},{"en":"The bond pays a coupon of 4% per annum.","zh-TW":"債券每年支付4%的票息。"}]', NULL, NULL, 3, 4886, NULL),
(4887, 'per capita', '/pɜːr ˈkæpɪtə/', 'adverb', '{"zh-TW":["每人；按人頭計"],"en":["for each person; per head of population"]}', NULL, 'per capita income / per capita consumption / per capita GDP', '[{"en":"Norway has one of the highest per capita incomes in the world.","zh-TW":"挪威擁有世界上最高的人均收入之一。"},{"en":"Per capita energy consumption has declined as efficiency standards improved.","zh-TW":"隨著效率標準的提高，人均能源消耗有所下降。"}]', NULL, NULL, 4, 4887, NULL),
(4888, 'per diem', '/pɜːr ˈdiːəm/', 'noun', '{"zh-TW":["每日津貼；日費"],"en":["a daily allowance paid to cover expenses while traveling for work"]}', NULL, 'per diem rate / claim per diem / per diem allowance', '[{"en":"Employees on business travel receive a per diem of 150 dollars.","zh-TW":"出差員工每天獲得150美元的日費津貼。"},{"en":"The per diem covers meals and incidental expenses.","zh-TW":"每日津貼涵蓋餐費和雜項支出。"}]', NULL, NULL, 3, 4888, NULL),
(4889, 'perceive', '/pərˈsiːv/', 'verb', '{"zh-TW":["感知；察覺","認為"],"en":["to become aware of","to regard as"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"ceive","meaning":"take (拿取)"}}', 'perceive as / perceive a threat / widely perceived', '[{"en":"The change was perceived as positive.","zh-TW":"這變化被認為是正面的。"},{"en":"Customers perceive our brand as reliable.","zh-TW":"客戶認為我們品牌可靠。"}]', '{"noun":"perception","adjective":"perceptive"}', NULL, 3, 4889, NULL),
(4890, 'percent', '/pərˈsɛnt/', 'noun', '{"zh-TW":["百分比"],"en":["one part in every hundred"]}', '{"prefix":{"text":"per-","meaning":"for each"},"root":{"text":"cent","meaning":"hundred (百)"}}', '50 percent / percent increase / percentage', '[{"en":"Sales increased by 15 percent.","zh-TW":"銷售增加了15%。"},{"en":"Only a small percent of applicants are accepted.","zh-TW":"只有少數申請者被錄取。"}]', '{"noun":"percentage"}', NULL, 3, 4890, NULL),
(4891, 'percentage', 'pərˈsɛntɪdʒ', 'noun', '{"zh-TW":["百分比；百分率","比率"],"en":["a proportion expressed as per 100","a rate"]}', NULL, 'high percentage/percentage increase', '[{"en":"A high percentage of customers returned.","zh-TW":"很高比例的客戶回購了。"}]', '{"adjective":"percentage","adverb":"by percentage"}', NULL, 4, 4891, 412),
(4892, 'perfect', 'ˈpɜːrfɪkt', 'adjective', '{"zh-TW":["完美的；理想的","完全的"],"en":["without faults","exactly right"]}', NULL, 'perfect solution/perfect timing', '[{"en":"This is the perfect time to launch.","zh-TW":"這是推出的完美時機。"}]', '{"verb":"perfect","noun":"perfection","adverb":"perfectly"}', NULL, 3, 4892, NULL),
(4893, 'perform', '/pərˈfɔːrm/', 'verb', '{"zh-TW":["表演；執行","執行；履行","表現"],"en":["to carry out an action","to entertain an audience","to carry out a task","to function or do well"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"form","meaning":"provide (提供)"},"logic":"徹底提供（表演），即「表演」。"}', 'perform a task / perform on stage; perform a task / perform well / perform duties', '[{"en":"The band will perform live tonight.","zh-TW":"樂團今晚將現場表演。"},{"en":"She performed the surgery successfully.","zh-TW":"她成功地執行了手術。"},{"en":"The system performs well under pressure.","zh-TW":"系統在壓力下表現良好。"},{"en":"Employees must perform their duties efficiently.","zh-TW":"員工必須有效履行職責。"}]', '{"noun":"performance","noun2":"performer"}', NULL, 3, 4893, 172),
(4894, 'performance', '/pərˈfɔːrməns/', 'noun', '{"zh-TW":["表演；表現"],"en":["an act of presenting entertainment; how well one does"]}', NULL, 'live performance / job performance', '[{"en":"The performance received great reviews.","zh-TW":"這場表演獲得了極好的評價。"},{"en":"His job performance improved greatly.","zh-TW":"他的工作表現大幅改善。"}]', '{"verb":"perform","noun2":"performer"}', NULL, 4, 4894, 603),
(4895, 'performance appraisal', '/pəˈfɔːrməns əˈpreɪzəl/', 'noun', '{"zh-TW":["績效考核"],"en":["a formal evaluation of an employee''s work performance"]}', NULL, 'conduct a performance appraisal / annual performance appraisal', '[{"en":"Managers complete a performance appraisal for each team member.","zh-TW":"管理者為每位團隊成員完成績效考核。"},{"en":"The annual performance appraisal determines salary increases.","zh-TW":"年度績效考核決定薪資增加。"}]', NULL, NULL, 5, 4895, NULL),
(4896, 'performance bond', '/pəˈfɔːrməns bɒnd/', 'noun', '{"zh-TW":["履約保證金；履約保函"],"en":["a bond issued to guarantee completion of a contract"]}', NULL, 'require a performance bond / issue a performance bond', '[{"en":"A performance bond was required before construction could begin.","zh-TW":"施工開始前需要提供履約保證金。"},{"en":"If the contractor fails to perform, the bond can be called.","zh-TW":"如果承包商未能履約，可以要求支付保函。"}]', NULL, NULL, 5, 4896, NULL),
(4897, 'performance bonus', '/pərˈfɔːrmənts ˈboʊnəs/', 'noun', '{"zh-TW":["績效獎金"],"en":["additional pay awarded for achieving or exceeding performance targets"]}', NULL, 'earn a performance bonus / performance bonus scheme / receive a performance bonus', '[{"en":"The team shared a performance bonus after exceeding annual targets.","zh-TW":"團隊在超越年度目標後共同分享了績效獎金。"},{"en":"Performance bonuses are tied to individual and company results.","zh-TW":"績效獎金與個人和公司業績掛鈎。"}]', NULL, NULL, 5, 4897, NULL),
(4898, 'performance gap', '/pəˈfɔːrmɪŋs ɡæp/', 'noun', '{"zh-TW":["績效差距"],"en":["the difference between actual performance and the desired or target performance"]}', NULL, 'identify a performance gap / close the performance gap', '[{"en":"The performance gap was addressed through targeted training and coaching.","zh-TW":"績效差距通過有針對性的培訓和輔導得到了解決。"},{"en":"Regular performance reviews help managers spot and address performance gaps early.","zh-TW":"定期績效評估幫助管理者早期發現和解決績效差距。"}]', NULL, NULL, 5, 4898, NULL),
(4899, 'performance management', '/pərˈfɔːrmənts ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["績效管理"],"en":["a continuous process of setting expectations, monitoring, and reviewing employee performance"]}', NULL, 'performance management system / effective performance management', '[{"en":"The performance management system was redesigned to be more frequent and actionable.","zh-TW":"績效管理系統被重新設計為更頻繁且可行動的。"},{"en":"Performance management aligns individual goals with company strategy.","zh-TW":"績效管理將個人目標與公司策略保持一致。"}]', NULL, NULL, 5, 4899, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4900, 'performance metric', '/pəˈfɔːrməns ˈmetrɪk/', 'noun', '{"zh-TW":["績效指標"],"en":["a measurable value used to evaluate how well something is performing"]}', NULL, 'set performance metrics / track performance metrics', '[{"en":"Key performance metrics are reviewed monthly by senior management.","zh-TW":"高級管理層每月審查關鍵績效指標。"},{"en":"Performance metrics help the team identify areas for improvement.","zh-TW":"績效指標幫助團隊識別改進領域。"}]', NULL, NULL, 5, 4900, NULL),
(4901, 'performance review', '/pərˈfɔːrmənts rɪˈvjuː/', 'noun', '{"zh-TW":["績效評估"],"en":["a regular formal evaluation of an employee''s work performance"]}', NULL, 'conduct a performance review / performance review cycle / annual performance review', '[{"en":"He was promoted following an excellent performance review.","zh-TW":"他在出色的績效評估後獲得晉升。"},{"en":"Performance reviews are held twice a year at this company.","zh-TW":"本公司每年進行兩次績效評估。"}]', '{"verb":"review performance"}', NULL, 5, 4901, NULL),
(4902, 'performance target', '/pəˈfɔːrməns ˈtɑːrɡɪt/', 'noun', '{"zh-TW":["績效目標"],"en":["a specific measurable goal set for an individual or team to achieve"]}', NULL, 'set performance targets / meet performance targets', '[{"en":"Individual performance targets are aligned with company objectives.","zh-TW":"個人績效目標與公司目標保持一致。"},{"en":"Bonuses are paid when staff achieve their performance targets.","zh-TW":"員工達到績效目標時支付獎金。"}]', NULL, NULL, 5, 4902, NULL),
(4903, 'performance-based', 'pərˈfɔːrməns beɪst', 'adjective', '{"zh-TW":["績效導向的；以績效為基礎的","按績效考核的"],"en":["based on measurable results","tied to output"]}', NULL, 'performance-based bonus/performance-based review', '[{"en":"Our compensation is performance-based.","zh-TW":"我們的薪酬是基於績效的。"}]', NULL, NULL, 5, 4903, NULL),
(4904, 'performance-enhancing', '/''pɜːrfɔːrməns ɪnˈhɑːnsɪŋ/', 'adjective', '{"zh-TW":["提高運動表現的"],"en":["designed to improve athletic performance, often associated with banned substances"]}', NULL, 'performance-enhancing drug / performance-enhancing substance / banned', '[{"en":"Athletes caught using performance-enhancing drugs face severe penalties.","zh-TW":"被發現使用提升運動表現藥物的運動員將面臨嚴厲的處罰。"},{"en":"Some athletes look for legal performance-enhancing methods like altitude training.","zh-TW":"一些運動員尋找合法的提升運動表現方法，例如高原訓練。"}]', NULL, NULL, 5, 4904, NULL),
(4905, 'perinatal', '/ˌperɪˈneɪtəl/', 'adjective', '{"zh-TW":["圍產期的"],"en":["relating to the time immediately before and after birth"]}', NULL, 'perinatal care / perinatal period / perinatal mortality', '[{"en":"Perinatal care focuses on health of both mother and newborn.","zh-TW":"圍產期護理關注母親和新生兒的健康。"},{"en":"Improved perinatal care has significantly reduced infant mortality.","zh-TW":"改善的圍產期護理顯著降低了嬰兒死亡率。"}]', '{"noun":"perinatology"}', NULL, 3, 4905, NULL),
(4906, 'period', '/ˈpɪriəd/', 'noun', '{"zh-TW":["期間；時期"],"en":["a length of time"]}', '{"root":{"text":"peri","meaning":"around (周圍)"}}', 'during this period / trial period / period of time', '[{"en":"Sales declined during this period.","zh-TW":"這段期間銷售下降。"},{"en":"The trial period is 90 days.","zh-TW":"試用期為90天。"}]', '{"adjective":"periodic, periodical","adverb":"periodically"}', NULL, 2, 4906, NULL),
(4907, 'periodic', '/ˌpɪəriˈɒdɪk/', 'adjective', '{"zh-TW":["定期的；週期性的"],"en":["occurring or recurring at regular intervals"]}', NULL, 'periodic reports / periodic review / periodic maintenance', '[{"en":"Periodic maintenance prevents costly equipment breakdowns.","zh-TW":"定期維護防止代價高昂的設備故障。"},{"en":"The contract requires periodic performance reports every quarter.","zh-TW":"合約要求每季提交定期績效報告。"}]', '{"adverb":"periodically","noun":"period"}', NULL, 3, 4907, NULL),
(4908, 'periodic payment', '/ˌpɪəriˈɒdɪk ˈpeɪmənt/', 'noun', '{"zh-TW":["定期付款"],"en":["a payment made at regular scheduled intervals"]}', NULL, 'set up periodic payments / automatic periodic payments', '[{"en":"The loan is repaid through 60 monthly periodic payments.","zh-TW":"貸款通過60個月的定期付款償還。"},{"en":"Periodic payments were adjusted annually for inflation.","zh-TW":"定期付款每年根據通脹調整。"}]', NULL, NULL, 5, 4908, NULL),
(4909, 'periodic review', '/ˌpɪəriˈɒdɪk rɪˈvjuː/', 'noun', '{"zh-TW":["定期審查"],"en":["a scheduled assessment of performance, contracts, or processes"]}', NULL, 'conduct a periodic review / periodic review schedule', '[{"en":"A periodic review of supplier contracts is conducted annually.","zh-TW":"供應商合約的定期審查每年進行一次。"},{"en":"Periodic reviews ensure the strategy remains relevant to market conditions.","zh-TW":"定期審查確保策略與市場條件保持相關性。"}]', NULL, NULL, 5, 4909, NULL),
(4910, 'peripheral', '/''pəˌrɪfərɪəl/', 'adjective', '{"zh-TW":["外圍的；次要的"],"en":["relating to or situated on the edge or periphery of something; of secondary or minor importance"]}', NULL, 'peripheral issue / peripheral vision / peripheral role', '[{"en":"The committee decided to focus on the main agenda and set aside peripheral issues.","zh-TW":"委員會決定專注於主要議程，將外圍問題放在一邊。"},{"en":"She played only a peripheral role in the project but still made valuable contributions.","zh-TW":"她在項目中只扮演了次要角色，但仍然做出了有價值的貢獻。"}]', '{"adverb":"peripherally","noun":"periphery"}', NULL, 4, 4910, NULL),
(4911, 'perishable', '/ˈperɪʃəbəl/', 'adjective', '{"zh-TW":["易腐的；易損壞的"],"en":["liable to decay or spoil quickly, especially of food products"]}', NULL, 'perishable goods / perishable cargo / handle perishables', '[{"en":"Perishable goods require refrigerated transport.","zh-TW":"易腐商品需要冷藏運輸。"},{"en":"The perishable cargo was given priority handling at the airport.","zh-TW":"易腐貨物在機場獲得了優先處理。"}]', '{"noun":"perishables"}', NULL, 4, 4911, NULL),
(4912, 'perishable goods', '/''perɪʃəbəl ɡʊdz/', 'noun', '{"zh-TW":["易腐貨物；易腐爛商品"],"en":["products that have a limited shelf life and can deteriorate if not stored and transported properly"]}', NULL, 'handle perishable goods / transport perishable goods / perishable goods logistics', '[{"en":"Perishable goods such as fresh fruit must be transported in refrigerated vehicles.","zh-TW":"新鮮水果等易腐貨物必須在冷藏車輛中運輸。"},{"en":"The cold chain ensures perishable goods maintain their quality throughout transport.","zh-TW":"冷鏈確保易腐貨物在整個運輸過程中保持其質量。"}]', NULL, NULL, 5, 4912, NULL),
(4913, 'perjury', '/ˈpɜːrdʒəri/', 'noun', '{"zh-TW":["偽證罪；作偽證"],"en":["the criminal offense of lying under oath in legal proceedings"]}', NULL, 'commit perjury / charge with perjury / perjury conviction', '[{"en":"The witness was charged with perjury after contradicting previous statements.","zh-TW":"證人因與之前的陳述矛盾而被指控作偽證。"},{"en":"Perjury undermines the integrity of the judicial process.","zh-TW":"偽證罪破壞了司法程序的完整性。"}]', '{"adjective":"perjurious","verb":"perjure"}', NULL, 3, 4913, NULL),
(4914, 'permafrost', '/ˈpɜːrməfrɒst/', 'noun', '{"zh-TW":["永久凍土"],"en":["ground that remains frozen throughout the year in arctic and subarctic regions"]}', NULL, 'thawing permafrost / arctic permafrost / permafrost degradation', '[{"en":"Thawing permafrost releases vast amounts of stored carbon.","zh-TW":"永久凍土融化釋放出大量儲存的碳。"},{"en":"Infrastructure in permafrost regions is increasingly unstable due to warming.","zh-TW":"由於暖化，永久凍土地區的基礎設施越來越不穩定。"}]', '{"adjective":"permafrost"}', NULL, 4, 4914, NULL),
(4915, 'permanent', '/ˈpɜːrmənənt/', 'adjective', '{"zh-TW":["永久的；長期的"],"en":["lasting forever or for a long time"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"man","meaning":"remain (留下)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'permanent position / permanent damage / permanent residence', '[{"en":"She was offered a permanent position.","zh-TW":"她獲得了正式職位。"},{"en":"The damage may be permanent.","zh-TW":"損害可能是永久的。"}]', '{"adverb":"permanently","noun":"permanence"}', NULL, 3, 4915, 413),
(4916, 'permeate', '/''pɜːrmiˌeɪt/', 'verb', '{"zh-TW":["滲透；瀰漫"],"en":["to spread throughout and be perceived in every part of something"]}', NULL, 'permeate throughout / permeate a culture / permeate society', '[{"en":"The smell of fresh coffee permeated throughout the office every morning.","zh-TW":"每天早上，新鮮咖啡的香氣滲透到整個辦公室。"},{"en":"A culture of excellence should permeate every level of the organization.","zh-TW":"卓越的文化應滲透到組織的每個層面。"}]', '{"noun":"permeation","adjective":"permeable"}', NULL, 3, 4916, NULL),
(4917, 'permit', '/pərˈmɪt/', 'verb', '{"zh-TW":["允許；許可"],"en":["to give permission for something","to allow something"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"讓其通過放行，即「允許」。"}', 'permit access / weather permitting / work permit; permit sb. to do / work permit / building permit', '[{"en":"Photography is not permitted inside the museum.","zh-TW":"博物館內不允許拍照。"},{"en":"The law does not permit this activity.","zh-TW":"法律不允許此活動。"},{"en":"Employees are not permitted to use personal phones.","zh-TW":"員工不允許使用個人手機。"},{"en":"You need a permit to park here.","zh-TW":"你需要許可證才能停這裡。"}]', '{"noun":"permit","noun2":"permission","adjective":"permissible"}', NULL, 2, 4917, 173),
(4918, 'perpetual', '/''pərˌpetʃuəl/', 'adjective', '{"zh-TW":["永久的；持續的；無休止的"],"en":["never ending or changing; occurring repeatedly; so frequent as to seem endless"]}', NULL, 'perpetual motion / perpetual conflict / in a perpetual state', '[{"en":"She seemed to be in a perpetual state of motion, always working on a new project.","zh-TW":"她似乎永遠處於運動狀態，總是在從事新項目。"},{"en":"The company faces perpetual pressure to innovate faster than its competitors.","zh-TW":"公司面臨著比競爭對手更快創新的持續壓力。"}]', '{"adverb":"perpetually","verb":"perpetuate","noun":"perpetuity"}', NULL, 3, 4918, NULL),
(4919, 'perpetuate', '/''pərˌpetʃuˌeɪt/', 'verb', '{"zh-TW":["使持續；使永久化"],"en":["to make something continue indefinitely; to preserve or maintain"]}', NULL, 'perpetuate a myth / perpetuate inequality / perpetuate a cycle', '[{"en":"Media stereotypes can perpetuate harmful misconceptions about certain groups.","zh-TW":"媒體刻板印象可能使對某些群體的有害誤解持續下去。"},{"en":"Education that ignores cultural differences can perpetuate systemic inequalities.","zh-TW":"忽視文化差異的教育可能使系統性不平等持續存在。"}]', '{"noun":"perpetuation","adjective":"perpetual"}', NULL, 4, 4919, NULL),
(4920, 'perpetuity', '/ˌpɜːrpɪˈtjuːɪti/', 'noun', '{"zh-TW":["永久；永續年金"],"en":["a bond or stream of income with no end date"]}', NULL, 'perpetuity bond / in perpetuity / perpetuity cash flow', '[{"en":"The asset generates cash flows in perpetuity.","zh-TW":"該資產永久產生現金流。"},{"en":"A growing perpetuity is used to value a company''s terminal value.","zh-TW":"成長永續年金用於評估公司的終值。"}]', '{"adjective":"perpetual","adverb":"perpetually"}', NULL, 4, 4920, NULL),
(4921, 'persist', '/pərˈsɪst/', 'verb', '{"zh-TW":["堅持；持續"],"en":["to continue firmly; to last"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'persist in / persist with / if problems persist', '[{"en":"If the problem persists, contact support.","zh-TW":"如問題持續，請聯繫支援。"},{"en":"She persisted in her efforts despite setbacks.","zh-TW":"儘管受挫她仍堅持努力。"}]', '{"noun":"persistence","adjective":"persistent","adverb":"persistently"}', NULL, 3, 4921, NULL),
(4922, 'person', 'ˈpɜːrsən', 'noun', '{"zh-TW":["人；個人","當事人"],"en":["a human being","a specific individual"]}', NULL, 'contact person/key person', '[{"en":"She is the key person for this account.","zh-TW":"她是這個帳戶的關鍵人物。"}]', '{"adjective":"personal","adverb":"personally"}', NULL, 2, 4922, NULL),
(4923, 'personal', '/ˈpɜːrsənəl/', 'adjective', '{"zh-TW":["個人的；私人的"],"en":["relating to a particular person"]}', '{"root":{"text":"person","meaning":"person (人)"},"suffix":{"text":"-al","meaning":"...的"}}', 'personal information / personal opinion / personal belongings', '[{"en":"Do not share personal information online.","zh-TW":"不要在網上分享個人資訊。"},{"en":"This is my personal opinion.","zh-TW":"這是我個人意見。"}]', '{"noun":"personality","adverb":"personally","verb":"personalize"}', NULL, 3, 4923, NULL),
(4924, 'personal best', '/''pɜːrsənəl best/', 'noun', '{"zh-TW":["個人最佳成績；個人紀錄"],"en":["the best performance a person has achieved in a particular sport or activity"]}', NULL, 'set a personal best / beat a personal best / achieve a personal best', '[{"en":"He shaved three seconds off his personal best in the 100-meter dash.","zh-TW":"他在百公尺短跑中打破了自己的個人最佳成績，快了三秒。"},{"en":"Setting a new personal best motivated her to continue training.","zh-TW":"設立新的個人最佳成績激勵她繼續訓練。"}]', NULL, NULL, 5, 4924, NULL),
(4925, 'personal liability', '/ˈpɜːrsənl laɪəˈbɪlɪti/', 'noun', '{"zh-TW":["個人責任；個人法律責任"],"en":["a director or owner being held personally responsible for business debts"]}', NULL, 'face personal liability / expose to personal liability', '[{"en":"Sole traders face personal liability for all business debts.","zh-TW":"個體經營者對所有商業債務承擔個人責任。"},{"en":"The court held the director personally liable for the company losses.","zh-TW":"法院追究董事對公司損失的個人責任。"}]', NULL, NULL, 5, 4925, NULL),
(4926, 'personal protective equipment', '/ˈpɜːrsənəl prəˈtɛktɪv ɪˈkwɪpmənt/', 'noun', '{"zh-TW":["個人防護裝備"],"en":["protective clothing and devices to minimize hazard exposure"]}', NULL, 'wear personal protective equipment / required personal protective equipment', '[{"en":"Personal protective equipment is mandatory on the construction site.","zh-TW":"建設工地上必須佩戴個人防護裝備。"},{"en":"Inspect personal protective equipment before each use.","zh-TW":"每次使用前請檢查個人防護裝備。"}]', '{"abbreviation":"PPE"}', NULL, 5, 4926, NULL),
(4927, 'personnel', '/ˌpɜːrsəˈnɛl/', 'noun', '{"zh-TW":["人員；員工"],"en":["the people employed in an organization"]}', '{"root":{"text":"person","meaning":"person (人)"}}', 'personnel department / key personnel / military personnel', '[{"en":"All personnel must attend the training.","zh-TW":"所有人員必須參加培訓。"},{"en":"The personnel department handles hiring.","zh-TW":"人事部門處理招聘。"}]', NULL, NULL, 3, 4927, 44),
(4928, 'perspective', '/pərˈspektɪv/', 'noun', '{"zh-TW":["觀點；角度","觀點；視角"],"en":["a particular way of viewing things","a way of thinking about something"]}', '{"prefix":{"text":"per-","meaning":"through (透過)"},"root":{"text":"spect","meaning":"look (看)"},"suffix":{"text":"-ive","meaning":"relating to (相關的)"},"logic":"透過某角度來看，即「觀點」。"}', 'from my perspective / gain perspective / new perspective; from a different perspective / put into perspective / gain perspective; from my perspective / gain a new perspective / put in perspective', '[{"en":"From my perspective, the plan makes sense.","zh-TW":"從我的角度來看，這個計畫合理。"},{"en":"Travel gives you a new perspective on life.","zh-TW":"旅行給你新的人生觀點。"},{"en":"Try to see it from the customer''s perspective.","zh-TW":"試從客戶角度看。"},{"en":"The report puts the data into perspective.","zh-TW":"報告讓數據更有脈絡。"},{"en":"From a financial perspective, the deal is good.","zh-TW":"從財務角度看，這筆交易不錯。"},{"en":"Travel helps you gain new perspectives.","zh-TW":"旅行幫助你獲得新的觀點。"}]', NULL, NULL, 4, 4928, 414),
(4929, 'persuade', '/pərˈsweɪd/', 'verb', '{"zh-TW":["說服"],"en":["to cause someone to do or believe something"]}', '{"prefix":{"text":"per-","meaning":"thoroughly"},"root":{"text":"suade","meaning":"advise (勸)"}}', 'persuade sb. to do / be persuaded', '[{"en":"She persuaded the board to approve the budget.","zh-TW":"她說服董事會批准預算。"},{"en":"I was persuaded by his argument.","zh-TW":"我被他的論點說服了。"}]', '{"noun":"persuasion","adjective":"persuasive","adverb":"persuasively"}', NULL, 3, 4929, NULL),
(4930, 'pertinent', '/ˈpɜːrtɪnənt/', 'adjective', '{"zh-TW":["相關的；切題的"],"en":["relevant or applicable to a particular matter"]}', NULL, 'pertinent information / pertinent question / highly pertinent', '[{"en":"She raised several pertinent questions about the methodology.","zh-TW":"她提出了幾個與方法論相關的問題。"},{"en":"Please include only pertinent data in the summary.","zh-TW":"請在摘要中只包含相關數據。"}]', '{"adverb":"pertinently","noun":"pertinence"}', NULL, 3, 4930, NULL),
(4931, 'pervasive', '/''pɜːrˈveɪsɪv/', 'adjective', '{"zh-TW":["普遍的；滲透性的"],"en":["spreading widely throughout an area or a group of people"]}', NULL, 'pervasive influence / pervasive problem / pervasive culture', '[{"en":"The pervasive influence of digital technology has transformed every industry.","zh-TW":"數字技術的普遍影響已轉變了每個行業。"},{"en":"A pervasive culture of innovation drives the company to constantly develop new ideas.","zh-TW":"普遍的創新文化驅使公司不斷發展新想法。"}]', '{"adverb":"pervasively","noun":"pervasiveness"}', NULL, 3, 4931, NULL),
(4932, 'perverse incentive', '/pɜːrˈvɜːrs ɪnˈsentɪv/', 'noun', '{"zh-TW":["負向誘因；扭曲激勵"],"en":["an incentive that has unintended and undesirable consequences contrary to the policy''s intentions"]}', NULL, 'create a perverse incentive / avoid perverse incentives / unintended perverse incentive', '[{"en":"Fee-for-service healthcare creates a perverse incentive to over-treat patients.","zh-TW":"按服務收費的醫療保健制度創造了過度治療患者的扭曲激勵。"},{"en":"Policies must be designed carefully to avoid creating perverse incentives.","zh-TW":"必須仔細設計政策，以避免產生扭曲的激勵機制。"}]', NULL, NULL, 5, 4932, NULL),
(4933, 'pessimistic', '/ˌpesɪˈmɪstɪk/', 'adjective', '{"zh-TW":["悲觀的"],"en":["tending to see the worst aspect of things"]}', '{"root":{"text":"pessim","meaning":"worst (最壞)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最壞面為特徵的，即「悲觀的」。"}', 'pessimistic view / pessimistic about', '[{"en":"He has a pessimistic view of the economy.","zh-TW":"他對經濟持悲觀看法。"},{"en":"Don''t be so pessimistic about everything.","zh-TW":"不要對所有事都那麼悲觀。"}]', '{"noun":"pessimism","noun2":"pessimist"}', NULL, 4, 4933, NULL),
(4934, 'petition', '/pɪˈtɪʃən/', 'noun', '{"zh-TW":["請願書","請願書；申請"],"en":["a formal written request signed by many people","a formal written request"]}', '{"root":{"text":"petit","meaning":"seek (尋求)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'sign a petition / online petition; file a petition / sign a petition', '[{"en":"Over 10,000 people signed the petition.","zh-TW":"超過一萬人簽署了請願書。"},{"en":"They started an online petition.","zh-TW":"他們發起了一份線上請願書。"},{"en":"Employees signed a petition for better conditions.","zh-TW":"員工簽署了改善條件的請願書。"},{"en":"She filed a petition with the court.","zh-TW":"她向法院提交了申請。"}]', '{"verb":"petition","noun":"petitioner"}', NULL, 3, 4934, NULL),
(4935, 'petty cash', '/ˈpɛti kæʃ/', 'noun', '{"zh-TW":["零用金；備用現金"],"en":["a small amount of cash kept for minor expenses"]}', NULL, 'petty cash fund / petty cash reimbursement', '[{"en":"Small office expenses can be paid from the petty cash fund.","zh-TW":"小額辦公費用可從零用金支付。"},{"en":"All petty cash transactions must be recorded and receipted.","zh-TW":"所有零用金交易必須記錄並保留收據。"}]', NULL, NULL, 4, 4935, NULL),
(4936, 'petty cash voucher', '/ˈpɛti kæʃ ˈvaʊtʃər/', 'noun', '{"zh-TW":["零用金憑單"],"en":["a document used to authorize and record petty cash payments"]}', NULL, 'complete a petty cash voucher / petty cash voucher system', '[{"en":"Fill in a petty cash voucher for every cash payment under twenty dollars.","zh-TW":"每次20元以下的現金付款都需填寫零用金憑單。"},{"en":"All petty cash vouchers must be approved by a supervisor.","zh-TW":"所有零用金憑單必須獲得主管批准。"}]', NULL, NULL, 5, 4936, NULL),
(4937, 'pharmaceutical', '/ˌfɑːrməˈsuːtɪkəl/', 'adjective', '{"zh-TW":["製藥的；藥物的"],"en":["relating to the preparation and dispensing of drugs"]}', NULL, 'pharmaceutical company / pharmaceutical product', '[{"en":"The pharmaceutical company launched a new drug this year.","zh-TW":"製藥公司今年推出了一種新藥。"},{"en":"Pharmaceutical research requires years of clinical trials.","zh-TW":"製藥研究需要多年的臨床試驗。"}]', '{"noun":"pharmacist","noun2":"pharmacy"}', NULL, 5, 4937, NULL),
(4938, 'pharmacist', '/ˈfɑːrməsɪst/', 'noun', '{"zh-TW":["藥劑師"],"en":["a person licensed to prepare and dispense medications"]}', NULL, 'consult a pharmacist / licensed pharmacist / hospital pharmacist', '[{"en":"The pharmacist reviewed potential drug interactions before dispensing.","zh-TW":"藥劑師在發藥前審查了潛在的藥物交互作用。"},{"en":"Pharmacists advise patients on how to use their medications correctly.","zh-TW":"藥劑師建議患者如何正確使用藥物。"}]', '{"noun2":"pharmacy"}', NULL, 4, 4938, NULL),
(4939, 'pharmacokinetics', '/ˌfɑːrməkəʊkɪˈnetɪks/', 'noun', '{"zh-TW":["藥物代謝動力學"],"en":["the study of how the body absorbs, distributes, and eliminates drugs"]}', NULL, 'pharmacokinetics study / pharmacokinetics profile / pharmacokinetics data', '[{"en":"Pharmacokinetics determines how frequently a drug must be taken.","zh-TW":"藥物代謝動力學決定了藥物必須服用的頻率。"},{"en":"The new formulation improved the pharmacokinetics of the compound.","zh-TW":"新製劑改善了化合物的藥物代謝動力學。"}]', '{"adjective":"pharmacokinetic"}', NULL, 5, 4939, NULL),
(4940, 'pharmacy', '/ˈfɑːrməsi/', 'noun', '{"zh-TW":["藥局；藥房"],"en":["a shop where medicines are dispensed and sold"]}', NULL, 'local pharmacy / hospital pharmacy', '[{"en":"Pick up your prescription at the pharmacy.","zh-TW":"在藥局領取您的處方藥。"},{"en":"The pharmacy is open until 10 pm.","zh-TW":"藥局開到晚上10點。"}]', '{"noun":"pharmacist","adjective":"pharmaceutical"}', NULL, 3, 4940, NULL),
(4941, 'pharmacy benefit', '/ˈfɑːrməsi ˈbɛnɪfɪt/', 'noun', '{"zh-TW":["藥品福利"],"en":["insurance coverage for prescription medications"]}', NULL, 'pharmacy benefit plan / pharmacy benefit management', '[{"en":"The pharmacy benefit plan covers most common prescriptions.","zh-TW":"藥品福利計劃涵蓋大多數常用處方藥。"},{"en":"Review your pharmacy benefit to understand medication coverage.","zh-TW":"查看您的藥品福利以了解藥物承保範圍。"}]', NULL, NULL, 5, 4941, NULL),
(4942, 'phase', '/feɪz/', 'noun', '{"zh-TW":["階段；時期"],"en":["a distinct stage in a process"]}', NULL, 'first phase / phase out / phase in / implementation phase', '[{"en":"The project is now in its final phase.","zh-TW":"項目現在處於最後階段。"},{"en":"We will phase out the old system gradually.","zh-TW":"我們將逐步淘汰舊系統。"}]', '{"verb":"phase"}', NULL, 2, 4942, 174),
(4943, 'phased implementation', '/feɪzd ˌɪmplɪmenˈteɪʃən/', 'noun', '{"zh-TW":["分階段實施"],"en":["rolling out a project or system in stages rather than all at once"]}', NULL, 'plan a phased implementation / phased implementation schedule', '[{"en":"A phased implementation reduced risk by limiting early disruption.","zh-TW":"分階段實施通過限制早期中斷降低了風險。"},{"en":"The software upgrade used a phased implementation to allow staff training.","zh-TW":"軟件升級採用了分階段實施方式，以便員工培訓。"}]', NULL, NULL, 5, 4943, NULL),
(4944, 'phenomenological', '/fɪˌnɒmɪnəˈlɒdʒɪkəl/', 'adjective', '{"zh-TW":["現象學的"],"en":["relating to the study of conscious experience as lived by individuals"]}', NULL, 'phenomenological approach / phenomenological study / phenomenological research', '[{"en":"The phenomenological study explored patients'' lived experiences of pain.","zh-TW":"現象學研究探索了患者對疼痛的生活體驗。"},{"en":"A phenomenological approach focuses on subjective meaning.","zh-TW":"現象學方法關注主觀意義。"}]', '{"noun":"phenomenology","adverb":"phenomenologically"}', NULL, 5, 4944, NULL),
(4945, 'phenomenon', '/fɪˈnɒmɪnən/', 'noun', '{"zh-TW":["現象"],"en":["a fact or situation that is observed"]}', '{"root":{"text":"pheno","meaning":"appear (出現)"}}', 'natural phenomenon / social phenomenon', '[{"en":"This is a common phenomenon in the industry.","zh-TW":"這是行業中的常見現象。"},{"en":"Remote work has become a global phenomenon.","zh-TW":"遠程工作已成為全球現象。"}]', '{"adjective":"phenomenal","adverb":"phenomenally"}', NULL, 4, 4945, NULL),
(4946, 'philanthropical', '/ˌfɪlənˈθrɒpɪkəl/', 'adjective', '{"zh-TW":["慈善的；博愛的"],"en":["motivated by a desire to help others, especially by donating money"]}', NULL, 'philanthropical foundation / philanthropical endeavor / philanthropical goals', '[{"en":"The philanthropical foundation donated millions to fund cancer research globally.","zh-TW":"慈善基金會捐款數百萬用於在全球範圍內資助癌症研究。"},{"en":"Her philanthropical efforts improved access to clean water in remote villages.","zh-TW":"她的慈善努力改善了偏遠村莊獲取清潔水的機會。"}]', '{"adverb":"philanthropically","noun":"philanthropy"}', NULL, 5, 4946, NULL),
(4947, 'philanthropy', '/fɪˈlænθrəpi/', 'noun', '{"zh-TW":["慈善事業；慈善精神"],"en":["the practice of promoting welfare of others through donations"]}', NULL, 'corporate philanthropy / strategic philanthropy / philanthropic giving', '[{"en":"Corporate philanthropy plays an increasingly important role in communities.","zh-TW":"企業慈善事業在社區中扮演著越來越重要的角色。"},{"en":"Strategic philanthropy aligns charitable giving with organizational goals.","zh-TW":"戰略慈善將慈善捐贈與組織目標相結合。"}]', '{"adjective":"philanthropic","noun2":"philanthropist","adverb":"philanthropically"}', NULL, 4, 4947, NULL),
(4948, 'phishing', '/ˈfɪʃɪŋ/', 'noun', '{"zh-TW":["網路釣魚"],"en":["a fraudulent attempt to steal information via fake emails or sites"]}', NULL, 'phishing attack / phishing email', '[{"en":"Employees should be trained to recognize phishing emails.","zh-TW":"應訓練員工識別網路釣魚電子郵件。"},{"en":"The IT team blocked a sophisticated phishing attack.","zh-TW":"IT團隊阻止了一次複雜的網路釣魚攻擊。"}]', NULL, NULL, 3, 4948, NULL),
(4949, 'phone', 'foʊn', 'noun', '{"zh-TW":["電話；手機","通話"],"en":["a device for voice communication","a call"]}', NULL, 'answer the phone/phone call', '[{"en":"Please answer the phone within three rings.","zh-TW":"請在三聲鈴響內接聽電話。"}]', '{"verb":"phone","adjective":"phone-based"}', NULL, 2, 4949, NULL);
