(4950, 'photovoltaic', '/ˌfəʊtəʊvɒlˈteɪɪk/', 'adjective', '{"zh-TW":["光伏的；太陽能電池的"],"en":["relating to the generation of electricity from sunlight"]}', NULL, 'photovoltaic system / photovoltaic panel / photovoltaic energy', '[{"en":"Photovoltaic panels convert sunlight directly into electricity.","zh-TW":"光伏板將陽光直接轉化為電力。"},{"en":"The cost of photovoltaic energy has fallen dramatically over the past decade.","zh-TW":"過去十年光伏能源的成本大幅下降。"}]', '{"noun":"photovoltaic"}', NULL, 4, 4950, NULL),
(4951, 'physical inventory', '/ˈfɪzɪkəl ˈɪnvəntəri/', 'noun', '{"zh-TW":["實地盤點"],"en":["the actual counting of all physical stock held at a location"]}', NULL, 'conduct a physical inventory / physical inventory count', '[{"en":"A physical inventory is conducted at every quarter end.","zh-TW":"每季度末進行實地盤點。"},{"en":"Discrepancies found during physical inventory trigger an investigation.","zh-TW":"實地盤點中發現的差異會引發調查。"}]', NULL, NULL, 5, 4951, NULL),
(4952, 'physical therapist', '/''fɪzɪkəl ˌθerəpɪst/', 'noun', '{"zh-TW":["物理治療師"],"en":["a healthcare professional who helps people improve or restore physical movement and manage pain"]}', NULL, 'see a physical therapist / consult a physical therapist / licensed physical therapist', '[{"en":"Her doctor referred her to a physical therapist after her knee surgery.","zh-TW":"她的醫生在她膝蓋手術後將她轉介給物理治療師。"},{"en":"The physical therapist designed a customized rehabilitation program for the injured player.","zh-TW":"物理治療師為受傷球員設計了個人化的康復計劃。"}]', '{"noun":"physical therapy"}', NULL, 5, 4952, NULL),
(4953, 'physical therapy', '/ˈfɪzɪkəl ˈθɛrəpi/', 'noun', '{"zh-TW":["物理治療"],"en":["treatment using physical methods such as exercise and massage"]}', NULL, 'attend physical therapy / physical therapy sessions', '[{"en":"Physical therapy helped her regain strength after the surgery.","zh-TW":"物理治療幫助她在手術後恢復了力量。"},{"en":"The doctor recommended twice-weekly physical therapy.","zh-TW":"醫生建議每週兩次物理治療。"}]', '{"noun":"physiotherapist"}', NULL, 5, 4953, NULL),
(4954, 'physiotherapy', '/''fɪziəʊˌθerəpi/', 'noun', '{"zh-TW":["物理治療；復健治療"],"en":["treatment of disease, injury, or deformity by physical methods such as exercise and massage"]}', NULL, 'need physiotherapy / physiotherapy session / physiotherapy clinic', '[{"en":"After the knee surgery, she required six months of physiotherapy to recover fully.","zh-TW":"膝蓋手術後，她需要六個月的物理治療才能完全康復。"},{"en":"Regular physiotherapy helped the athlete return to competition ahead of schedule.","zh-TW":"定期物理治療幫助運動員提前回到了賽場。"}]', '{"noun":"physiotherapist"}', NULL, 5, 4954, NULL),
(4955, 'physique', '/''fɪˈziːk/', 'noun', '{"zh-TW":["體型；體格"],"en":["the form, size, and development of a person''s body"]}', NULL, 'athletic physique / lean physique / develop a physique', '[{"en":"Years of dedicated training gave the swimmer an impressive physique.","zh-TW":"多年的專注訓練使這位游泳運動員擁有了令人印象深刻的體格。"},{"en":"A strong physique is important for contact sports like rugby and wrestling.","zh-TW":"強壯的體格對於橄欖球和摔跤等接觸性運動非常重要。"}]', NULL, NULL, 3, 4955, NULL),
(4956, 'phytoremediation', '/ˌfaɪtəʊˌriːmidiˈeɪʃən/', 'noun', '{"zh-TW":["植物修復"],"en":["the use of plants to clean up contaminated soil or water"]}', NULL, 'use phytoremediation / phytoremediation project / phytoremediation of heavy metals', '[{"en":"Phytoremediation uses specific plant species to absorb soil contaminants.","zh-TW":"植物修復使用特定植物物種來吸收土壤污染物。"},{"en":"Sunflowers have been used for phytoremediation after nuclear contamination.","zh-TW":"向日葵在核污染後被用於植物修復。"}]', NULL, NULL, 5, 4956, NULL),
(4957, 'pick', '/pɪk/', 'verb', '{"zh-TW":["挑選；撿起"],"en":["to choose","to take up with fingers"]}', NULL, 'pick up / hand-picked', '[{"en":"I will pick you up at the airport.","zh-TW":"我去機場接你。"},{"en":"She was hand-picked for the role.","zh-TW":"她是被精心挑選擔任這個職位的。"}]', '{"verb":"pick","noun":"pick","adjective":"picky"}', NULL, 1, 4957, NULL),
(4958, 'picture', '/ˈpɪktʃər/', 'noun', '{"zh-TW":["圖片；情況"],"en":["a visual image","a situation or description"]}', NULL, 'big picture / get the picture', '[{"en":"Let''s focus on the big picture.","zh-TW":"讓我們關注大局。"},{"en":"Do you get the picture?","zh-TW":"你了解情況了嗎？"}]', '{"noun":"picture","verb":"picture"}', NULL, 3, 4958, NULL),
(4959, 'pie chart', '/paɪ tʃɑːrt/', 'noun', '{"zh-TW":["圓餅圖；扇形圖"],"en":["a circular chart divided into sectors showing proportions"]}', NULL, 'include a pie chart / pie chart breakdown', '[{"en":"The pie chart illustrates the budget allocation clearly.","zh-TW":"圓餅圖清楚地說明了預算分配情況。"},{"en":"A pie chart is ideal for showing percentage breakdowns.","zh-TW":"圓餅圖非常適合顯示百分比分解。"}]', NULL, NULL, 3, 4959, NULL),
(4960, 'piece', '/piːs/', 'noun', '{"zh-TW":["一片；一件"],"en":["a part of something","a single item"]}', NULL, 'a piece of advice / fall into place', '[{"en":"Let me give you a piece of advice.","zh-TW":"讓我給你一個建議。"},{"en":"Everything is falling into place.","zh-TW":"一切都步入正軌了。"}]', '{"noun":"piece"}', NULL, 2, 4960, NULL),
(4961, 'pier', '/''pɪər/', 'noun', '{"zh-TW":["碼頭；棧橋"],"en":["a structure leading out from land over water, used as a promenade or for landing vessels"]}', NULL, 'walk along the pier / fishing pier / embark from the pier', '[{"en":"The ferry departs from the pier on the east side of the harbor.","zh-TW":"渡輪從海港東側的碼頭出發。"},{"en":"The pier was crowded with fishermen on Sunday morning.","zh-TW":"星期天早上，碼頭上擠滿了漁夫。"}]', NULL, NULL, 1, 4961, NULL),
(4962, 'pilgrimage', '/''pɪlɡrɪmɪdʒ/', 'noun', '{"zh-TW":["朝聖之旅；聖地之旅"],"en":["a journey to a sacred or important place as an act of devotion"]}', NULL, 'make a pilgrimage / undertake a pilgrimage / sacred pilgrimage', '[{"en":"Thousands of pilgrims make the pilgrimage to Santiago de Compostela each year.","zh-TW":"每年有數千名朝聖者前往聖地亞哥德孔波斯特拉朝聖。"},{"en":"For fans, visiting the author''s birthplace felt like a pilgrimage.","zh-TW":"對書迷來說，參觀這位作者的出生地感覺像是一次朝聖之旅。"}]', '{"verb":"make a pilgrimage","adjective":"pilgrim"}', NULL, 4, 4962, NULL),
(4963, 'pilot program', '/ˈpaɪlət ˈproʊɡræm/', 'noun', '{"zh-TW":["試點計劃"],"en":["a small-scale preliminary study to evaluate a new idea before full implementation"]}', NULL, 'run a pilot program / launch a pilot program / pilot program results', '[{"en":"The chatbot was introduced as a pilot program in two stores.","zh-TW":"聊天機器人在兩家門市作為試點計劃引入。"},{"en":"The pilot program proved successful and will be rolled out nationwide.","zh-TW":"試點計劃取得了成功，將在全國推廣。"}]', NULL, NULL, 5, 4963, NULL),
(4964, 'pilot project', '/ˈpaɪlət ˈprɒdʒɛkt/', 'noun', '{"zh-TW":["試行計劃；試點項目"],"en":["a small-scale test of a program before full implementation"]}', NULL, 'launch a pilot project / pilot project results', '[{"en":"The company ran a pilot project before rolling out nationwide.","zh-TW":"公司在全國推廣之前進行了試行計劃。"},{"en":"Lessons learned from the pilot project improved the final design.","zh-TW":"從試行計劃中學到的經驗改善了最終設計。"}]', NULL, NULL, 5, 4964, NULL),
(4965, 'pilot test', '/ˈpaɪlət test/', 'noun', '{"zh-TW":["試驗；試點測試"],"en":["a small-scale trial to evaluate feasibility before full implementation"]}', NULL, 'conduct a pilot test / results of the pilot test', '[{"en":"A pilot test was conducted in two stores before the national rollout.","zh-TW":"在全國推廣前在兩家門市進行了試驗。"},{"en":"Pilot test results were used to refine the new system.","zh-TW":"試點測試結果用於完善新系統。"}]', '{"verb":"pilot test","adjective":"pilot-tested"}', NULL, 4, 4965, NULL),
(4966, 'pioneer', '/ˌpaɪəˈnɪr/', 'noun', '{"zh-TW":["先驅；開拓者"],"en":["a person who is among the first to do something"]}', NULL, 'pioneer in the field / pioneer of technology', '[{"en":"She was a pioneer in the field of AI.","zh-TW":"她是AI領域的先驅。"},{"en":"The company pioneered online shopping.","zh-TW":"該公司開創了線上購物。"}]', '{"verb":"pioneer","adjective":"pioneering"}', NULL, 3, 4966, 706),
(4967, 'pipeline', '/ˈpaɪplaɪn/', 'noun', '{"zh-TW":["銷售管道；流水線"],"en":["the set of potential deals in various stages of the sales process"]}', NULL, 'sales pipeline / build the pipeline / pipeline management / pipeline review', '[{"en":"The sales team has a healthy pipeline of $5 million in deals.","zh-TW":"銷售團隊擁有價值500萬美元的健康銷售管道。"},{"en":"Pipeline reviews help forecast future revenue accurately.","zh-TW":"管道審查幫助準確預測未來收入。"}]', NULL, NULL, 3, 4967, 905),
(4968, 'pipeline revenue', '/ˈpaɪplaɪn ˈrevɪnjuː/', 'noun', '{"zh-TW":["管道收入；潛在收入"],"en":["expected future revenue from deals currently in progress"]}', NULL, 'track pipeline revenue / pipeline revenue forecast', '[{"en":"The sales team''s pipeline revenue suggests strong growth next quarter.","zh-TW":"銷售團隊的管道收入顯示下季度將有強勁增長。"},{"en":"Pipeline revenue analysis helps management assess future cash flow.","zh-TW":"管道收入分析幫助管理層評估未來現金流。"}]', NULL, NULL, 5, 4968, NULL),
(4969, 'pitch', '/pɪtʃ/', 'noun', '{"zh-TW":["推銷；提案"],"en":["a presentation aimed at persuading someone to buy or invest"]}', NULL, 'sales pitch / pitch to investors', '[{"en":"His sales pitch convinced the client to sign the contract.","zh-TW":"他的推銷說服了客戶簽署合約。"},{"en":"The startup made a compelling pitch to venture capitalists.","zh-TW":"初創公司向風險資本家做了引人注目的提案。"}]', '{"verb":"pitch","adjective":"pitched"}', NULL, 2, 4969, NULL),
(4970, 'pitch deck', '/''pɪtʃ dek/', 'noun', '{"zh-TW":["商業計劃簡報；融資提案"],"en":["a presentation given to potential investors or clients outlining a business idea or proposal"]}', NULL, 'create a pitch deck / present a pitch deck / compelling pitch deck', '[{"en":"He created a compelling pitch deck that persuaded three investors to fund his startup.","zh-TW":"他創作了一個有說服力的商業計劃簡報，說服三位投資者資助他的新創公司。"},{"en":"A good pitch deck should be concise and visually engaging, covering key business metrics.","zh-TW":"一個好的商業計劃簡報應該簡潔且視覺上吸引人，涵蓋關鍵業務指標。"}]', NULL, NULL, 4, 4970, NULL),
(4971, 'pivot', '/ˈpɪvət/', 'verb', '{"zh-TW":["轉向；業務轉型"],"en":["to change a company''s strategy or business model significantly"]}', NULL, 'pivot the business / startup pivot / strategic pivot', '[{"en":"The startup pivoted from B2C to B2B after market research.","zh-TW":"新創公司在市場研究後從B2C轉向B2B。"},{"en":"Pivoting to digital services saved the company during the crisis.","zh-TW":"轉向數位服務在危機期間救了公司。"}]', '{"noun":"pivot","adjective":"pivotal"}', NULL, 2, 4971, NULL),
(4972, 'pivotal', '/ˈpɪvɪtəl/', 'adjective', '{"zh-TW":["關鍵的；核心的"],"en":["of crucial importance in relation to the development or success of something"]}', NULL, 'pivotal role / pivotal moment / pivotal decision', '[{"en":"The CEO played a pivotal role in turning the company around.","zh-TW":"執行長在公司轉型中發揮了關鍵作用。"},{"en":"This is a pivotal moment for the organization''s future direction.","zh-TW":"這是組織未來方向的關鍵時刻。"}]', '{"adverb":"pivotally","noun":"pivot"}', NULL, 3, 4972, NULL),
(4973, 'place', '/pleɪs/', 'noun', '{"zh-TW":["地方；位置"],"en":["a particular area or position"]}', NULL, 'in place / take place', '[{"en":"The meeting will take place on Monday.","zh-TW":"會議將在週一舉行。"},{"en":"New policies are now in place.","zh-TW":"新政策現已到位。"}]', '{"noun":"place","verb":"place","noun2":"placement"}', NULL, 2, 4973, 175),
(4974, 'placebo', '/pləˈsiːbəʊ/', 'noun', '{"zh-TW":["安慰劑"],"en":["an inactive treatment given to a control group in a clinical trial"]}', NULL, 'placebo effect / placebo-controlled trial / receive a placebo', '[{"en":"The control group received a placebo rather than the active drug.","zh-TW":"對照組接受了安慰劑而非活性藥物。"},{"en":"The placebo effect demonstrates the power of expectation in healing.","zh-TW":"安慰劑效應展示了期望在癒合中的力量。"}]', '{"adjective":"placebo"}', NULL, 3, 4974, NULL),
(4975, 'placement', '/ˈpleɪsmənt/', 'noun', '{"zh-TW":["實習安置；分班"],"en":["the process of placing students in jobs or classes"]}', NULL, 'job placement / placement test', '[{"en":"The university has an excellent job placement record.","zh-TW":"這所大學有出色的就業安置記錄。"},{"en":"A placement test determines which course level suits you.","zh-TW":"分班測試確定哪個課程級別適合您。"}]', '{"verb":"place","adjective":"placed"}', NULL, 3, 4975, 906),
(4976, 'plagiarism', '/ˈpleɪdʒərɪzəm/', 'noun', '{"zh-TW":["抄襲；剽竊"],"en":["taking someone else''s work and presenting it as your own","using someone''s work as your own without credit"]}', NULL, 'avoid plagiarism / plagiarism check', '[{"en":"The company has strict policies against plagiarism.","zh-TW":"公司有嚴格的反抄襲政策。"},{"en":"All content goes through a plagiarism check.","zh-TW":"所有內容都要經過抄襲檢查。"},{"en":"Plagiarism is a serious offense.","zh-TW":"抄襲是嚴重的違規行為。"},{"en":"The software detects plagiarism.","zh-TW":"這軟體能偵測抄襲。"}]', '{"noun":"plagiarism","verb":"plagiarize","noun2":"plagiarist"}', NULL, 4, 4976, NULL),
(4977, 'plagiarism detection', '/''pleɪdʒɪˌrɪzəm dɪˌtekʃən/', 'noun', '{"zh-TW":["抄襲檢測"],"en":["the process or technology used to identify instances where text has been copied without attribution"]}', NULL, 'use plagiarism detection software / plagiarism detection tool / automatic plagiarism detection', '[{"en":"The university requires all essays to pass plagiarism detection before submission.","zh-TW":"大學要求所有文章在提交前通過抄襲檢測。"},{"en":"Plagiarism detection software has made it easier for teachers to identify copied work.","zh-TW":"抄襲檢測軟件使老師更容易識別抄襲的作業。"}]', '{"verb":"detect","noun":"plagiarism"}', NULL, 5, 4977, NULL),
(4978, 'plain language', '/''pleɪn ˌlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["簡明語言；通俗語言"],"en":["writing or speech that is clear, concise, and easily understood by its intended audience"]}', NULL, 'write in plain language / plain language guide / use plain language', '[{"en":"Government communications should be written in plain language for all citizens to understand.","zh-TW":"政府通訊應以簡明語言撰寫，讓所有公民都能理解。"},{"en":"The manual was rewritten in plain language to make it more accessible to users.","zh-TW":"手冊以簡明語言重新撰寫，使用戶更容易理解。"}]', NULL, NULL, 5, 4978, NULL),
(4979, 'plaintiff', '/ˈpleɪntɪf/', 'noun', '{"zh-TW":["原告"],"en":["the person who brings a case to court"]}', NULL, 'the plaintiff argued / plaintiff''s attorney', '[{"en":"The plaintiff filed the lawsuit.","zh-TW":"原告提起了訴訟。"},{"en":"The plaintiff''s claims were dismissed.","zh-TW":"原告的訴求被駁回了。"}]', NULL, NULL, 3, 4979, NULL),
(4980, 'plan', '/plæn/', 'noun', '{"zh-TW":["計畫"],"en":["a detailed proposal for doing something"]}', NULL, 'action plan / plan ahead', '[{"en":"We need a clear action plan.","zh-TW":"我們需要一個明確的行動計畫。"},{"en":"Always plan ahead for busy periods.","zh-TW":"永遠要提前規劃忙碌時期。"}]', '{"noun":"plan","verb":"plan","noun2":"planner","noun3":"planning"}', NULL, 1, 4980, 176),
(4981, 'planning', 'ˈplænɪŋ', 'noun', '{"zh-TW":["規劃；計畫","策劃"],"en":["the process of making plans","organizing for the future"]}', NULL, 'strategic planning/advance planning', '[{"en":"Good planning prevents project failures.","zh-TW":"良好的規劃可以防止專案失敗。"}]', '{"verb":"plan","adjective":"planned"}', NULL, 3, 4981, 605),
(4982, 'planning cycle', '/ˈplænɪŋ ˈsaɪkəl/', 'noun', '{"zh-TW":["規劃週期"],"en":["the recurring process of setting goals, executing plans, and reviewing results"]}', NULL, 'enter the planning cycle / annual planning cycle', '[{"en":"The annual planning cycle kicks off in October for the next year.","zh-TW":"年度規劃週期在十月啟動為下一年做準備。"},{"en":"A structured planning cycle improves strategic alignment.","zh-TW":"結構化的規劃週期改善了戰略一致性。"}]', NULL, NULL, 5, 4982, NULL),
(4983, 'planning permission', '/ˈplænɪŋ pəˈmɪʃən/', 'noun', '{"zh-TW":["規劃許可；建築許可"],"en":["official approval to build or make changes to a property"]}', NULL, 'obtain planning permission / apply for planning permission', '[{"en":"The developer obtained planning permission before construction began.","zh-TW":"開發商在施工開始前獲得了規劃許可。"},{"en":"Planning permission was refused due to concerns about traffic impact.","zh-TW":"由於對交通影響的擔憂，規劃許可被拒絕了。"}]', NULL, NULL, 5, 4983, NULL),
(4984, 'plant', '/plɑːnt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】植物；工廠；設備","【次要意義-動詞】安插；秘密放置（某物/某人）","【次要意義-動詞】安置；建立（機構）"],"en":["[primary - noun] a living organism; a factory or industrial facility","[secondary - verb] to place secretly or covertly in a location","[secondary - verb] to establish an idea or organization in a place"]}', NULL, 'manufacturing plant / power plant / plant evidence / plant an idea', '[{"en":"The new manufacturing plant will create over 500 jobs.","zh-TW":"新的製造工廠將創造逾500個工作崗位。"},{"en":"Investigators suspected that the evidence had been planted.","zh-TW":"調查人員懷疑證據是被人為安插的。"},{"en":"The company plans to plant its first overseas subsidiary in Singapore.","zh-TW":"公司計劃在新加坡建立第一個海外子公司。"}]', '{"noun":"plantation","adjective":"planted"}', 'plant 作名詞指「工廠/設備」（manufacturing plant），動詞 plant = 「秘密安置/安插」，這些次要意義在 TOEIC 工業或調查報導類文章中出現，容易與「種植」混淆。', 2, 4984, NULL),
(4985, 'plant-based', '/''plɑːnt beɪst/', 'adjective', '{"zh-TW":["植物性的；以植物為基礎的"],"en":["consisting of or derived from plants; relating to a diet centered on plant foods"]}', NULL, 'plant-based diet / plant-based protein / plant-based meal', '[{"en":"More consumers are switching to a plant-based diet for health and environmental reasons.","zh-TW":"越來越多的消費者出於健康和環境原因轉向植物性飲食。"},{"en":"Plant-based burgers have improved dramatically in taste and texture in recent years.","zh-TW":"近年來，植物性漢堡在口感和質地上有了顯著改善。"}]', NULL, NULL, 4, 4985, NULL),
(4986, 'plant-based diet', '/''plɑːnt beɪst ˌdaɪɪt/', 'noun', '{"zh-TW":["以植物為主的飲食；植物性飲食"],"en":["a diet that focuses primarily on foods derived from plants, including vegetables, grains, and legumes"]}', NULL, 'follow a plant-based diet / switch to a plant-based diet / plant-based diet benefit', '[{"en":"A plant-based diet is associated with lower risks of heart disease and diabetes.","zh-TW":"植物性飲食與較低的心臟病和糖尿病風險有關。"},{"en":"The restaurant''s new menu features entirely plant-based dishes.","zh-TW":"餐廳的新菜單全部採用植物性菜餚。"}]', '{"adjective":"plant-based"}', NULL, 5, 4986, NULL),
(4987, 'plastic waste', '/ˈplæstɪk weɪst/', 'noun', '{"zh-TW":["塑膠廢棄物"],"en":["discarded plastic materials that pollute the environment"]}', NULL, 'reduce plastic waste / plastic waste crisis', '[{"en":"Ocean plastic waste harms marine life significantly.","zh-TW":"海洋塑膠廢棄物對海洋生物造成嚴重危害。"},{"en":"The company pledged to eliminate single-use plastic waste.","zh-TW":"公司承諾消除一次性塑膠廢棄物。"}]', NULL, NULL, 5, 4987, NULL),
(4988, 'platform', '/ˈplætfɔːrm/', 'noun', '{"zh-TW":["平台"],"en":["a system for running applications"]}', NULL, 'social media platform / online platform', '[{"en":"Which platform do you use?","zh-TW":"你用哪個平台？"},{"en":"The company launched a new platform.","zh-TW":"公司推出了一個新平台。"}]', NULL, NULL, 3, 4988, NULL),
(4989, 'plating', '/''pleɪtɪŋ/', 'noun', '{"zh-TW":["擺盤；食物呈現方式"],"en":["the arrangement of food on a plate in an aesthetically pleasing way"]}', NULL, 'creative plating / beautiful plating / food plating technique', '[{"en":"The chef spent as much time on plating as he did on cooking the dish.","zh-TW":"廚師在擺盤上花費的時間和烹飪一樣多。"},{"en":"Skillful plating can transform a simple dish into a fine dining experience.","zh-TW":"精湛的擺盤可以將一道簡單的菜肴轉變為精緻餐飲體驗。"}]', '{"verb":"plate"}', NULL, 3, 4989, NULL),
(4990, 'plausible', '/''plɔːzɪbəl/', 'adjective', '{"zh-TW":["似乎合理的；可信的"],"en":["seeming reasonable or probable; having an appearance of truth or reason"]}', NULL, 'plausible explanation / plausible scenario / plausible reason', '[{"en":"The consultant offered a plausible explanation for the unexpected decline in sales.","zh-TW":"顧問為意外的銷售下降提供了一個似乎合理的解釋。"},{"en":"She presented a plausible argument for restructuring the product line.","zh-TW":"她為重組產品線提出了一個可信的論點。"}]', '{"adverb":"plausibly","noun":"plausibility"}', NULL, 3, 4990, NULL),
(4991, 'play', '/pleɪ/', 'verb', '{"zh-TW":["扮演；玩"],"en":["to take part in a game","to perform a role"]}', NULL, 'play a role / fair play', '[{"en":"Technology plays a key role in our strategy.","zh-TW":"科技在我們的策略中扮演關鍵角色。"},{"en":"We believe in fair play.","zh-TW":"我們相信公平競爭。"}]', '{"verb":"play","noun":"play","noun2":"player"}', NULL, 1, 4991, NULL),
(4992, 'playoffs', '/''pleɪˌɒfs/', 'noun', '{"zh-TW":["季後賽；淘汰賽"],"en":["a series of games or matches contested by teams or players who have qualified for the final stage of a competition"]}', NULL, 'make the playoffs / reach the playoffs / playoff round', '[{"en":"The team qualified for the playoffs by finishing second in the regular season.","zh-TW":"球隊以常規賽第二名的成績晉級季後賽。"},{"en":"Playoff performances are often more intense than regular season games.","zh-TW":"季後賽的表現通常比常規賽更激烈。"}]', NULL, NULL, 3, 4992, NULL),
(4993, 'pledge', '/plɛdʒ/', 'verb', '{"zh-TW":["承諾；保證"],"en":["to make a formal promise"]}', NULL, 'pledge support / pledge to do sth.', '[{"en":"The CEO pledged to reduce emissions.","zh-TW":"執行長承諾減少排放。"},{"en":"They pledged their full support.","zh-TW":"他們承諾全力支持。"}]', '{"noun":"pledge"}', NULL, 2, 4993, NULL),
(4994, 'plenary session', '/ˈpliːnəri ˈseʃən/', 'noun', '{"zh-TW":["全體大會；全體會議"],"en":["a meeting attended by all participants of a conference or assembly"]}', NULL, 'hold a plenary session / open the plenary session', '[{"en":"The conference opened with a plenary session featuring keynote speakers.","zh-TW":"會議以主題演講的全體大會揭幕。"},{"en":"All delegates attended the plenary session for the formal vote.","zh-TW":"所有代表出席了正式投票的全體會議。"}]', NULL, NULL, 5, 4994, NULL),
(4995, 'plug adapter', '/''plʌɡ əˌdæptər/', 'noun', '{"zh-TW":["電源轉接頭；插頭轉換器"],"en":["a device used to convert a plug from one type of electrical socket to another"]}', NULL, 'universal plug adapter / travel plug adapter / buy a plug adapter', '[{"en":"A universal plug adapter is essential for international travelers.","zh-TW":"萬用電源轉接頭對國際旅行者來說是必需品。"},{"en":"She forgot her plug adapter and couldn''t charge her laptop in the hotel room.","zh-TW":"她忘了帶電源轉接頭，無法在飯店房間為筆記型電腦充電。"}]', NULL, NULL, 4, 4995, NULL),
(4996, 'plunge', '/plʌndʒ/', 'verb', '{"zh-TW":["暴跌；驟降"],"en":["to fall or drop suddenly"]}', NULL, 'plunge into / stock prices plunged / take the plunge', '[{"en":"Stock prices plunged after the announcement.","zh-TW":"公告後股價暴跌。"},{"en":"She decided to take the plunge and start her own business.","zh-TW":"她決定冒險創業。"}]', '{"noun":"plunge"}', NULL, 2, 4996, NULL),
(4997, 'pluralism', '/ˈplʊərəlɪzəm/', 'noun', '{"zh-TW":["多元主義；多元論"],"en":["a condition in which many different groups exist in a society"]}', NULL, 'cultural pluralism / political pluralism / value pluralism', '[{"en":"The study defends pluralism as the basis of democratic society.","zh-TW":"該研究捍衛多元主義作為民主社會的基礎。"},{"en":"Pluralism in research methods strengthens scientific knowledge.","zh-TW":"研究方法的多元主義增強了科學知識。"}]', '{"adjective":"pluralistic","noun":"pluralist"}', NULL, 3, 4997, NULL),
(4998, 'pluralistic', '/ˌplʊərəˈlɪstɪk/', 'adjective', '{"zh-TW":["多元的；多元主義的"],"en":["relating to a system that includes multiple groups or perspectives"]}', NULL, 'pluralistic society / pluralistic democracy / pluralistic approach', '[{"en":"A pluralistic democracy values diversity of opinion and representation.","zh-TW":"多元民主重視意見和代表性的多樣性。"},{"en":"Pluralistic research methodologies capture a fuller picture of reality.","zh-TW":"多元研究方法論捕捉了現實的更完整圖景。"}]', '{"noun":"pluralism","adverb":"pluralistically"}', NULL, 4, 4998, NULL),
(4999, 'podium', '/ˈpəʊdiəm/', 'noun', '{"zh-TW":["講台；演講台"],"en":["a raised platform from which a speaker addresses an audience"]}', NULL, 'stand at the podium / address from the podium', '[{"en":"She confidently took the podium to deliver her speech.","zh-TW":"她自信地走上講台發表演講。"},{"en":"The presenter stood at the podium throughout the keynote.","zh-TW":"演講者在主題演講期間一直站在講台上。"}]', NULL, NULL, 2, 4999, NULL);